def crear_jornadas_historicas(apps, schema_editor):
    Asistencia = apps.get_model('academico', 'Asistencia')
    Jornada = apps.get_model('academico', 'JornadaAsistencia')
    Incidencia = apps.get_model('academico', 'IncidenciaMigracionAcademica')

    pendientes = Asistencia.objects.filter(jornada_id=None).order_by('fecha', 'grado_id')
    for asistencia in pendientes.iterator():
        if not asistencia.sede_id or not asistencia.periodo_id or not asistencia.grado_id:
            Incidencia.objects.get_or_create(
                tipo='asistencia_sin_jornada',
                modelo='academico.Asistencia',
                objeto_id=asistencia.pk,
                defaults={'detalle': {
                    'fecha': str(asistencia.fecha),
                    'sede_id': asistencia.sede_id,
                    'periodo_id': asistencia.periodo_id,
                    'grado_id': asistencia.grado_id,
                }},
            )
            continue
        jornada, _ = Jornada.objects.get_or_create(
            sede_id=asistencia.sede_id,
            periodo_id=asistencia.periodo_id,
            grado_id=asistencia.grado_id,
            fecha=asistencia.fecha,
            defaults={'version': 1, 'creada_por_id': asistencia.registrado_por_id},
        )
        asistencia.jornada_id = jornada.pk
        asistencia.save(update_fields=['jornada'])


